function reject(prompt,flags,notes){const q=questions.find(x=>x.prompt===prompt);if(!q)return;q.review.status="rejected";q.quality.status="rejected";q.quality.flags=flags;q.quality.notes=notes}
function rewrite(prompt,nextPrompt,notes){const q=questions.find(x=>x.prompt===prompt);if(!q)return;q.prompt=nextPrompt;q.revision++;q.quality.status="rewritten";q.quality.notes=notes;q.fact.sources=q.fact.sources.map(s=>({...s,verifiedAt:VERIFIED_AT,confirmsAnswer:true,confirmsWording:true}))}
const thriller=questions.find(q=>q.prompt==="Which artist released the album Thriller?");if(thriller){thriller.prompt="Which Michael Jackson album includes 'Beat It' and 'Billie Jean'?";thriller.answer.canonical="Thriller";thriller.answer.accepted.en=["thriller"];thriller.revision=2;thriller.quality.status="rewritten";thriller.quality.notes="Rewritten before approval to avoid a Batch 1 duplicate and provide a stronger clue."}
